% This is an autogenerated sample test for file STLExtractor.m
classdef testSTLExtractor < matlab.unittest.TestCase

    properties (TestParameter)
       nParticles = {48,100,200};
       largeFile = {
           "packing_parameters_5_4_success.stl",...
           "packing_parameters_15_1_success.stl",...
           "packing_parameters_20_1_success.stl"}
    end
    methods (Test)

        function test_process_can_identify_number_of_triangles(testCase,nParticles)
            testFileDir = fullfile(projectDir,"tests","test_stl_files");

            workingDir = "test_output";


            for i = nParticles
                
                filename = fullfile(testFileDir,['particles_',num2str(i),'.stl']);
                e = STLExtractor(filename,workingDir);
                ep = e.process();
                
                testCase.verifyEqual(length(ep), i);

            end


        end

        function test_process_can_parse_one_particle(testCase)
            testFileDir = fullfile(projectDir,"tests","test_stl_files");
            tol = 1e-3;
            workingDir = "test_output"; 
            basenames = [...
                "particle_r_1_t_1_c_0_0_0_n_0_0_1.stl",...
                "particle_r_2_t_3_c_0_0_0_n_0_1_0.stl" ,...
                ];
            for basename = basenames
                filename = fullfile(testFileDir,basename);
                e = STLExtractor(filename,workingDir);
                % Exercise the function obj.process
                ep = e.process();
    
                testCase.verifyEqual(length(ep), 1);
    
                prism = ep.items(1);
    
                tokens = regexp(filename,'particle_r_(\d)_t_(\d)_c_(\d)_(\d)_(\d)_n_(\d)_(\d)_(\d)*','tokens');
                tokens = tokens{1};
                radius = str2double(tokens{1});
                thickness = str2double(tokens{2});
    
                center = [str2double(tokens{3}),str2double(tokens{4}),str2double(tokens{5})];
                normal = [str2double(tokens{6}),str2double(tokens{7}),str2double(tokens{8})];
                normal = normal./norm(normal);
                testCase.verifyLessThanOrEqual(abs(prism.radius-radius),tol);
                testCase.verifyLessThanOrEqual(abs(prism.thickness-thickness),tol);

                % if the normal is the xy-axis, it doesn't matter whether the
                % axis is flipped
                isParallelToX = abs(...
                    abs(dot(prism.normal,[1,0,0])) - 1.0) < tol;
                isParallelToY = abs(...
                    abs(dot(prism.normal,[0,1,0])) - 1.0) < tol;

                if isParallelToX || isParallelToY
                testCase.verifyLessThanOrEqual(abs(abs(prism.normal)-normal),tol);
                else
                    testCase.verifyLessThanOrEqual(abs(prism.normal-normal),tol);
                end
                testCase.verifyLessThanOrEqual(abs(prism.position-center),tol);

            end


        end
    
        function test_can_process_larger_packings(testCase,largeFile)

                testFileDir = fullfile(projectDir,"tests","test_stl_files");
                filename = fullfile(testFileDir,largeFile);
                e = STLExtractor(filename,[],"ShouldSave",false);
                l = e.process();

                testCase.verifyNotEmpty(l);

        end

        function test_can_process_larger_packings_with_min_z_threshold(testCase,largeFile)

                testFileDir = fullfile(projectDir,"tests","test_stl_files");
                filename = fullfile(testFileDir,largeFile);
                e = STLExtractor(filename,[],"ShouldSave",false);
                l = e.process("ZMinLimit",0.2);

                testCase.verifyNotEmpty(l);

        end

        function test_can_cutoff_large_packings_with_disconnected_particles(testCase)

                testFileDir = fullfile(projectDir,"tests","test_stl_files");

                % this is a "problematic" file that, in addition of being large in size.
                % has a couple of particles that are disconected from the main packing
                % we want to test that we can process and cutoff this, 
                % if given a suitable z-value, and eliminating particles
                % whose z-position is larger than that
                problematicLargeFile = "packing_parameters_20_1_success.stl";
                filename = fullfile(testFileDir,problematicLargeFile);
                e = STLExtractor(filename,[],"ShouldSave",false);
                % bounding-box length, hard-coded from where the given file above
                % was produced
                L = 1.0;
                % this packing was generated assuming a higher bound for the density of
                % 1.0, but we know from experience that the packings have around 66% 
                % density. So we can make an estimative of how high is the packing
                zmax = (1/0.66)*L;
                l = e.process("ZMaxLimit",zmax);
                cutoff = 0.15;
                ep = l.cutoff(cutoff,"x");

                testCase.verifyNotEmpty(ep);

        end

        function test_rejects_particle_without_unique_axial_edges(testCase)
            filename = tempname + ".stl";
            cleanup = onCleanup(@() deleteIfExists(filename));

            points = [
                0, 0, 0;
                1, 0, 0;
                0, 1, 0;
                0, 0, 1
            ];
            faces = [
                1, 2, 3;
                1, 4, 2;
                2, 4, 3;
                1, 3, 4
            ];
            stlwrite(triangulation(faces, points), filename);

            extractor = STLExtractor(filename, [], "ShouldSave", false);
            try
                extractor.process();
                testCase.verifyFail("Expected unsupported geometry to be rejected.");
            catch ME
                testCase.verifyEqual(ME.identifier, ...
                    'STLExtractor:STLExtractor:InvalidParticleGeometry');
                testCase.verifyTrue(contains(ME.message, "Particle 1"));
                testCase.verifyTrue(contains(ME.message, ...
                    "expected exactly one group of 12 parallel edges"));
                testCase.verifyTrue(contains(ME.message, "found 0"));
            end
        end

        function test_rejects_malformed_stl_input(testCase)
            filename = tempname + ".stl";
            cleanup = onCleanup(@() deleteIfExists(filename));

            fid = fopen(filename, "w");
            testCase.assertGreaterThan(fid, 0);
            fprintf(fid, "not an stl file");
            fclose(fid);

            extractor = STLExtractor(filename, [], "ShouldSave", false);

            testCase.verifyError(@() extractor.process(), ...
                "MATLAB:polyfun:stlFailedToRead");
        end

